/**
 * Lightweight Store Implementation
 *
 * A minimal replacement for zustand/vanilla that provides the same API
 * without the dependency. Suitable for non-React environments.
 *
 * ```js
 * import { createStore } from '@three-blocks/pro';
 *
 * const store = createStore( ( set, get ) => ( {
 *   count: 0,
 *   inc: () => set( { count: get().count + 1 } ),
 * } ) );
 *
 * const unsubscribe = store.subscribe( ( next ) => console.log( next.count ) );
 * store.getState().inc();
 * unsubscribe();
 * ```
 *
 * @module @three-blocks/pro/store/createStore
 * @private
 * @short Minimal store utilities compatible with zustand/vanilla APIs.
 * @category Store
 * @tags Store, State, Utilities
 */
/**
 * Shallow compare two values for equality.
 * Handles primitives, arrays, and plain objects.
 *
 * @param {*} a - First value
 * @param {*} b - Second value
 * @returns {boolean} True if shallowly equal
 */
export function shallow(a: any, b: any): boolean;
/**
 * Create a vanilla store with get/set/subscribe API.
 * Compatible with zustand/vanilla createStore.
 *
 * @param {Function} createState - State initializer function (set, get) => initialState
 * @returns {Object} Store with getState, setState, subscribe, getInitialState
 */
export function createStore(createState: Function): any;
/**
 * Middleware that adds subscribeWithSelector to a store.
 * Allows subscribing to specific slices of state.
 *
 * @param {Function} createState - State initializer function
 * @returns {Function} Enhanced createStore function
 */
export function subscribeWithSelector(createState: Function): Function;
/**
 * Create a store with selector-based subscriptions.
 * Subscribers only fire when their selected slice changes.
 *
 * @param {Function} createState - State initializer function
 * @returns {Object} Store with enhanced subscribe
 */
export function createStoreWithSelector(createState: Function): any;
export default createStore;
